async () => {
  const out=[];
  let doc=document;
  for (let p=1;p<=17;p++){
    if(p>1){
      const f=doc.forms[0]; const fd=new FormData(f);
      fd.set('__EVENTTARGET','gv'); fd.set('__EVENTARGUMENT','Page$'+p);
      const r=await fetch('/Devices.aspx',{method:'POST',body:new URLSearchParams(fd)});
      doc=new DOMParser().parseFromString(await r.text(),'text/html');
    }
    doc.querySelectorAll('tr').forEach(r=>{const t=r.innerText?.replace(/\s+/g,' ').trim()||[...r.children].map(c=>c.textContent.trim()).join(' '); if(/D\d{4}/.test(t)&&r.children.length==5) out.push(p+': '+[...r.children].map(c=>c.textContent.trim()).join(' '))});
  }
  return out.filter(l=>/ 10(04|11|26) /.test(l)).join('\n')+'\nTOTAL '+out.length;
}

