async () => {
  async function scan(url, n){
    const out=[]; let doc=null;
    const first=await (await fetch(url)).text(); doc=new DOMParser().parseFromString(first,'text/html');
    for(let p=1;p<=n;p++){
      if(p>1){const fd=new FormData(doc.forms[0]); fd.set('__EVENTTARGET','gv'); fd.set('__EVENTARGUMENT','Page$'+p);
        doc=new DOMParser().parseFromString(await (await fetch(url,{method:'POST',body:new URLSearchParams(fd)})).text(),'text/html');}
      doc.querySelectorAll('tr').forEach(r=>{if(r.children.length==5&&/Delete/.test(r.textContent)) out.push([...r.children].slice(1,4).map(c=>c.textContent.trim()).join(' | '))});
    }
    const pages=[...doc.querySelectorAll('a[href*="Page$"]')].map(a=>a.getAttribute('href')).length;
    return out;
  }
  const res=await scan('/Residents.aspx',10), dev=await scan('/Devices.aspx',17);
  return {resTotal:res.length, res:res.filter(l=>/\| 10(04|11|26) \|/.test(l)||/Alder/.test(l)&&false), devTotal:dev.length, dev:dev.filter(l=>/ 10(04|11|26) /.test(l)), resAll1004_1011_1026: res.filter(l=>/ (1004|1011|1026) /.test(l)), devSample:dev.filter(l=>/D00(07|08|2[12])/.test(l))};
}

